'use client'

import * as React from 'react'


// The two components a story is made of. These imports come first on purpose:
// an ES module's imports are evaluated in source order, so every stylesheet
// below this line has already been injected by the time `story.css` is, and a
// rule in story.css wins a tie with one in media-frame.css or hud.css. That
// ordering is the only guarantee the library has, and it exists because story
// depends on them rather than because anything schedules it.
import { MediaFrame, type MediaFormat } from './media-frame'
import { Hud, type HudProps } from './hud'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Story, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './story.css'

// The shared action type and press gesture. Without this import a customer
// receives primitives.css and nothing points at it, so `.gs-action-type` and
// `.gs-pressable` match the controls below and the rules never arrive
// (GSUI-118).
import './gamestage-primitives.css'

/**
 * Story: the vertical format from specimen 3h. A sequence of frames a player
 * moves through, with the game's own state laid over the top.
 *
 * It is `media-frame` plus `hud` and a set of controls, and it owns no more of
 * the media than `media-frame` does. It does not play, advance on its own,
 * count elapsed time or decide that a frame is finished. The host owns `step`
 * and the story tells it which way the player asked to go; a story that
 * advanced itself would be a player with a timer in it, which is the thing the
 * media group exists not to be.
 *
 * **The pager is a placeholder and is meant to be deleted.** See the comment on
 * `StoryPager` below.
 */

export interface StoryFrame {
  /** The host's own id for this frame. Also what keeps React's list stable. */
  id?: string
  /**
   * What belongs in this frame, in the host's words. It is the frame's
   * accessible name and the words its empty state shows, so it is required for
   * the reason `media-frame` requires it.
   */
  label: string
  /** The caption plate under the media. The design's "Swipe a driver right…". */
  detail?: string
  /** The host's media for this frame. Omit it and the frame renders empty. */
  media?: React.ReactNode
  /** The host has been asked for this frame's media and has not answered. */
  busy?: boolean
  /** Playback is running on this frame. The host's word, never inferred. */
  playing?: boolean
  /**
   * How far through this frame playback is, 0 to 1. The host's word, for the
   * same reason as `playing`: the story has never touched the media and cannot
   * know. It fills the current cell of the pager, which is what the drawing
   * shows; absent, the cell stays hollow.
   */
  progress?: number
}

export interface StoryAction {
  /** The word on the control, which is the verb of its outcome. */
  label: string
  /** What the host does about it. The story does nothing else with the press. */
  onAction?: () => void
  /** Not available. Distinct from locked, which this component does not use. */
  disabled?: boolean
}

export interface StoryProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children' | 'onChange'> {
  /** The frames, in order. One element per frame, always rendered in the pager. */
  frames: StoryFrame[]
  /**
   * Which frame the player is on, 1-based. The host owns it: the story renders
   * the step it is given and never moves on its own. Out-of-range values are
   * clamped rather than thrown, because a sequence must not be able to crash a
   * screen on an off-by-one.
   */
  step?: number
  /** Called with the step the player asked for. The host decides what happens. */
  onStep?: (step: number) => void
  /** The sequence's own name, read beside the count: the design's "How to play". */
  title?: string
  /** The shape the frames hold. Defaults to `portrait`, which is what 3h draws. */
  format?: MediaFormat
  /** The exact ratio, as `width:height`, when the format's default is not it. */
  ratio?: string
  /** The game state laid over the media. Rendered as a `hud`, which owns it. */
  hud?: HudProps
  /** Leaving the sequence. Omit `onSkip` and no Skip control renders. */
  onSkip?: () => void
  /** The word on the Skip control. */
  skipLabel?: string
  /** The one thing to do from here: the design's full-width "TRY IT NOW". */
  action?: StoryAction
  /** The word for the whole sequence, for a screen reader. */
  label?: string
  /** The words on the two step controls, for a host that localises. */
  previousLabel?: string
  nextLabel?: string
}

/**
 * Inline SVG taking `currentColor`, never an emoji: an emoji carries its own
 * palette, ignores the theme and renders differently on every platform.
 * `aria-hidden`, because the button around it carries the name.
 */
function Chevron({ back }: { back?: boolean }) {
  return (
    <svg viewBox="0 0 16 16" width="1em" height="1em" fill="none" aria-hidden="true" focusable="false">
      <path
        d={back ? 'M10 3 5 8l5 5' : 'M6 3l5 5-5 5'}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/**
 * The pager: which frame of how many, as a row of cells.
 *
 * **PLACEHOLDER. Do not copy this, and do not build a third one.** The shared
 * segmented track is GSUI-115, shipping as the `segments` component with
 * `presentation="pager"`, and it was not on `main` when this was written. The
 * same object is drawn three times in the design: the round indicator on 3b,
 * the segmented progress on 3c and this pager on 3h. Three names for one track
 * is exactly what GSUI-115 exists to prevent, so this is deliberately the
 * thinnest thing that renders, it is private to this file, and it emits the
 * same per-segment attributes `segments` emits, `data-gs-step`,
 * `data-gs-active` and `data-gs-complete`, so a test written against it
 * survives the swap.
 *
 * Folding it in is GSUI-126: delete this function, import `segments`, add
 * `@gamestage/segments` to `story.json`'s registryDependencies.
 *
 * It is a readout, not a control. The design draws it as one, and the frames
 * are reachable from the two step controls below, so making each cell pressable
 * would add a second way to do the same thing and a focus order to maintain.
 * `role="list"` with a named item each, so it is readable without colour and
 * without shape.
 */
function StoryPager({ total, current, progress }: { total: number; current: number; progress?: number }) {
  // Clamped for the drawing only, the same way stat clamps its marks: the
  // host's number is the host's, and a fill cannot run past its cell.
  const fill = progress === undefined ? undefined : Math.min(1, Math.max(0, progress))
  return (
    <div className="gs-story__pager" data-gs-scope="story" data-gs-part="track" role="list">
      {Array.from({ length: total }, (_, index) => {
        const position = index + 1
        const done = position < current
        const active = position === current
        // Each cell is announced on its own, because "3 of 5" does not say
        // which three are behind. Position first, so the list reads in order.
        const words = [`${position}`, done ? 'complete' : active ? 'current' : 'to go']
        return (
          <span
            key={position}
            className="gs-story__segment"
            data-gs-scope="story" data-gs-part="step"
            data-gs-step={position}
            data-gs-complete={done ? 'true' : undefined}
            data-gs-active={active ? 'true' : undefined}
            style={active && fill !== undefined ? { ['--gs-story-progress' as string]: `${fill * 100}%` } : undefined}
            role="listitem"
            aria-label={words.join(', ')}
          />
        )
      })}
    </div>
  )
}

/** Clamped rather than thrown: an off-by-one must not be able to blank a screen. */
export function clampStep(step: number, total: number): number {
  if (total < 1) return 1
  if (!Number.isFinite(step)) return 1
  return Math.min(total, Math.max(1, Math.trunc(step)))
}

export function Story({
  frames,
  step = 1,
  onStep,
  title,
  format = 'portrait',
  ratio,
  hud,
  onSkip,
  skipLabel = 'Skip',
  action,
  label = 'story',
  previousLabel = 'previous',
  nextLabel = 'next',
  className,
  ...rest
}: StoryProps) {
  const total = frames.length
  const current = clampStep(step, total)
  const frame = frames[current - 1]

  const atStart = current <= 1
  const atEnd = current >= total

  // The name carries the sequence, because a screen reader user gets no pager
  // and no chevrons. What it is, then where it is.
  const words = [title, label, total > 0 ? `${current} of ${total}` : 'nothing here yet'].filter(
    Boolean,
  )

  return (
    <div
      {...rest}
      className={['gs-story', className].filter(Boolean).join(' ')}
      data-gs-component="story"
      data-gs-format={format}
      // No frames means no position to be at, so the attribute is absent
      // rather than claiming step 1 of 0 to anything reading the pair.
      data-gs-step={total > 0 ? current : undefined}
      data-gs-max={total}
      role="group"
      aria-label={words.join(', ')}
    >
      {/*
        The media frame owns the space and the empty case. A story with no
        frames still renders one, so the screen has the same shape before the
        host's sequence arrives as after it. Busy and playing are the frame's
        and travel straight through untouched: the story knows no more about
        playback than the frame does, which is nothing.
      */}
      <MediaFrame
        label={frame?.label ?? title ?? label}
        format={format}
        ratio={ratio}
        busy={frame?.busy}
        playing={frame?.playing}
      >
        {frame?.media}
      </MediaFrame>

      {/*
        Everything the library lays over the host's media. The overlay itself
        takes no presses: a press that lands on the media belongs to the host,
        the same rule `stage` makes assertable for its own layers. Each control
        inside takes its own, because each is only as big as itself. There is no
        `data-gs-pointer-events` here because the contract scopes that attribute
        to a stage layer, and a story is not a stage; the rule is in story.css
        and stated here rather than borrowed.
      */}
      <div className="gs-story__overlay">
        <div className="gs-story__top">
          <StoryPager total={total} current={current} progress={frame?.progress} />

          <div className="gs-story__header">
            {title ? (
              <span className="gs-story__title" data-gs-scope="story" data-gs-part="label">
                {title}
              </span>
            ) : null}
            {/* aria-hidden: the group's name above already carries the count,
                and announcing it twice reads the position twice. */}
            <span className="gs-story__count" data-gs-scope="story" data-gs-part="summary" aria-hidden="true">
              {current} of {total}
            </span>
            {onSkip ? (
              <button
                type="button"
                className="gs-story__skip gs-action-type gs-pressable"
                data-gs-scope="story" data-gs-part="dismiss"
                onClick={onSkip}
              >
                {skipLabel}
              </button>
            ) : null}
          </div>

          {/* The game state over the media, as a hud, which owns every number
              in it. The story adds no number of its own and carries no
              data-gs-value: a container never repeats a value it contains. */}
          {hud ? <Hud placement="top-right" {...hud} /> : null}
        </div>

        {/* The two step controls. `decrement` and `increment` because a story's
            step is a bounded value and these are what move it, which is the
            same idea a stepper's two controls carry. Both stay mounted and go
            disabled at the ends, so the row does not reflow under a thumb
            reaching for it. */}
        <div className="gs-story__steps">
          <button
            type="button"
            className="gs-story__step-control gs-action-type gs-pressable"
            data-gs-scope="story" data-gs-part="decrement"
            onClick={() => onStep?.(current - 1)}
            disabled={atStart}
            data-gs-disabled={atStart ? 'true' : undefined}
            // Both, the way `button` does it. The native attribute stops the
            // event and takes the control out of the tab order; aria-disabled
            // is what the accessibility stage and .gs-pressable both read, and
            // a control carrying one without the other is the half-state the
            // gate exists to catch.
            aria-disabled={atStart || undefined}
            aria-label={previousLabel}
          >
            <Chevron back />
          </button>
          <button
            type="button"
            className="gs-story__step-control gs-action-type gs-pressable"
            data-gs-scope="story" data-gs-part="increment"
            onClick={() => onStep?.(current + 1)}
            disabled={atEnd}
            data-gs-disabled={atEnd ? 'true' : undefined}
            aria-disabled={atEnd || undefined}
            aria-label={nextLabel}
          >
            <Chevron />
          </button>
        </div>

        <div className="gs-story__bottom">
          {frame?.detail ? (
            <p className="gs-story__caption" data-gs-scope="story" data-gs-part="detail">
              {frame.detail}
            </p>
          ) : null}

          {action ? (
            <div className="gs-story__actions" data-gs-scope="story" data-gs-part="actions">
              <button
                type="button"
                className="gs-story__action gs-action-type gs-pressable"
                onClick={action.onAction}
                disabled={action.disabled}
                data-gs-disabled={action.disabled ? 'true' : undefined}
                aria-disabled={action.disabled || undefined}
                data-gs-variant="primary"
              >
                {action.label}
              </button>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/* Story. Every value comes from a token; nothing here is a literal colour.

   Specimen 3h draws the vertical story and design/twins/3h.json measures ours
   against it. The drawing writes four translucent darks and lights over the
   media as literal rgba values; each is mixed here from the edge or the ink at
   the drawing's opacity rather than written as a colour.

   Every rule is scoped through `.gs-story`, and that is the composition rule
   rather than a style preference. A bare `.gs-media-frame { … }` here would tie
   with the one in media-frame.css at 0,1,0, and a tie is decided by whichever
   stylesheet the bundler put last. Import order happens to favour story today,
   because story imports its children before its own CSS, but that holds only
   while one component depends on the other. */

.gs-story {
  position: relative;
  /* The media frame and the overlay share one cell, so the story is exactly as
     tall as the frame and the overlay never adds height of its own. */
  display: grid;
  isolation: isolate;
  border-radius: var(--gs-radius-lg);
  overflow: hidden;
}

.gs-story > * {
  grid-area: 1 / 1;
}

/* ---------------------------------------------------------- the overlay -- */

/* The layer the library owns, over the media the host owns. It takes no presses
   itself: a tap on the media belongs to the host, and this layer covers all of
   it. Each control inside takes its own, which is safe because each is only as
   big as itself.

   This is the same rule `stage` declares on its layers through
   `data-gs-pointer-events`. It is written here rather than borrowed, because
   that attribute is scoped to a stage layer and a story is not a stage.

   The scrim is the drawing's: dark at the top and the bottom so the words read
   over any picture, clear across the middle where the picture is the point. */
.gs-story__overlay {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-rows: auto 1fr auto;
  padding: var(--gs-space-inset);
  gap: var(--gs-space-3);
  pointer-events: none;
  background: linear-gradient(
    180deg,
    color-mix(in oklch, var(--gs-color-edge) 60%, transparent),
    transparent 22%,
    transparent 60%,
    color-mix(in oklch, var(--gs-color-edge) 85%, transparent)
  );
}

.gs-story__overlay button {
  pointer-events: auto;
}

.gs-story__top {
  display: grid;
  gap: var(--gs-space-gap);
  align-content: start;
}

/* ------------------------------------------------------------ the pager -- */

/* PLACEHOLDER, paired with StoryPager in story.tsx. The shared segmented track
   is GSUI-115, shipping as `segments` with `presentation="pager"`; folding this
   into it is GSUI-126. Kept to the smallest thing that renders so nobody grows
   a third track here by accident. */
.gs-story__pager {
  display: flex;
  gap: var(--gs-space-1);
}

/* A thin bar: hollow in a quarter of the ink where the player has not been,
   filled with reward where they have. The drawing draws them 6px and space.1
   is the nearest token. */
.gs-story__segment {
  position: relative;
  flex: 1 1 0;
  height: var(--gs-space-1);
  overflow: hidden;
  border-radius: var(--gs-radius-full);
  background: color-mix(in oklch, var(--gs-color-ink) 25%, transparent);
}

.gs-story__segment[data-gs-complete='true'] {
  background: var(--gs-color-reward);
}

/* Where the sequence is now: the hollow bar filling with reward as far as the
   host says playback has got. Without the host's number it stays hollow, and
   the cell's own name says "current" either way. */
.gs-story__segment[data-gs-active='true']::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--gs-story-progress, 0%);
  background: var(--gs-color-reward);
}

/* ----------------------------------------------------------- the header -- */

.gs-story__header {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
}

.gs-story__title {
  flex: 1 1 auto;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-ink);
}

.gs-story__count {
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  font-variant-numeric: tabular-nums;
  color: var(--gs-color-ink-secondary);
}

/* Skip is the quiet way out: a translucent pill in the label face, never the
   emphasis the one thing to do from here carries. The drawing's 36px has no
   size token; space.8 is the nearest. */
.gs-story__skip {
  margin-inline-start: auto;
  box-sizing: border-box;
  min-height: var(--gs-space-8);
  padding: 0 var(--gs-space-inset);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: normal;
  color: var(--gs-color-ink);
  background: color-mix(in oklch, var(--gs-color-edge) 40%, transparent);
  border: var(--gs-stroke-ui) solid color-mix(in oklch, var(--gs-color-ink) 35%, transparent);
  border-radius: var(--gs-radius-full);
  cursor: pointer;
}

/* ----------------------------------------------------- the step controls -- */

.gs-story__steps {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* A translucent disc either side, the medium control size, a chevron in it. */
.gs-story__step-control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  inline-size: var(--gs-size-control-medium);
  block-size: var(--gs-size-control-medium);
  padding: 0;
  font-size: var(--gs-size-icon-utility);
  color: var(--gs-color-ink);
  background: color-mix(in oklch, var(--gs-color-edge) 45%, transparent);
  border: var(--gs-stroke-ui) solid color-mix(in oklch, var(--gs-color-ink) 30%, transparent);
  border-radius: var(--gs-radius-full);
  cursor: pointer;
}

/* The chevron at the small-glyph weight, which is what a 16px mark needs to
   stay a stroke rather than a smear. */
.gs-story__step-control svg {
  stroke-width: var(--gs-stroke-glyph-small);
}

/* At the end of the sequence the control stays where it is and goes flat, so
   nothing reflows under a thumb already reaching for it. Flat plus the button's
   own `disabled` is how "not available" reads, and the browser stops it taking
   focus, so it is never a control a keyboard lands on with nothing to do. */
.gs-story__step-control[data-gs-disabled='true'] {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border-color: var(--gs-color-disabled);
  cursor: default;
}

.gs-story__skip:focus-visible,
.gs-story__step-control:focus-visible,
.gs-story__action:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* ----------------------------------------------- the caption and the act -- */

.gs-story__bottom {
  display: grid;
  gap: var(--gs-space-4);
  align-content: end;
}

/* The caption plate: a surface behind the words, as wide as the words, centred.
   The body face at the body size; the drawing sets it bold, and the body token
   carries 400, which is on the token request list. */
.gs-story__caption {
  margin: 0;
  justify-self: center;
  padding: var(--gs-space-3) var(--gs-space-4);
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  text-align: center;
  text-wrap: pretty;
  color: var(--gs-color-ink);
  background: color-mix(in oklch, var(--gs-color-edge) 70%, transparent);
  border-radius: var(--gs-radius-sm);
}

.gs-story__actions {
  display: grid;
}

/* The one thing to do from here, full width, carrying the primary emphasis. The
   type and the press gesture come from .gs-action-type and .gs-pressable in
   packages/tokens/primitives.css, so a theme reaches this control the same way
   it reaches a button. Ringed in the edge at the control radius, as the
   drawing has it. */
.gs-story__action {
  box-sizing: border-box;
  min-height: var(--gs-size-action);
  padding: 0 var(--gs-space-6);
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  box-shadow: var(--gs-depth-pressable);
  cursor: pointer;
}

.gs-story__action[data-gs-disabled='true'] {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border-color: var(--gs-color-disabled);
  box-shadow: none;
  cursor: default;
}

/* The hud lays over media rather than over a page, and a hud's own stylesheet
   already assumes that, so there is nothing to declare for it here. That is the
   result worth recording rather than an omission: the moment story styled
   `.gs-hud` it would be writing a rule whose winner depends on bundler order. */

/* Shared rule sets, so a theme axis reaches a component without the component
 * remembering to read it.
 *
 * The problem this solves, measured rather than predicted. Every theme axis used
 * to need every component to opt in by hand, one CSS property at a time, and
 * nothing detected a component that missed one. Four of the six stylesheets
 * using the action type read `--gs-type-action-text-transform` and two did not,
 * so the arcade theme's uppercase reached four controls and silently skipped
 * two. The press gesture was the same shape of problem across five files.
 *
 * At 25 components that is an afternoon of patching. At 45 it is a permanent tax
 * and a permanent source of themes that are half applied, because the failure is
 * always silent: a missing line looks exactly like a theme that chose not to
 * change anything.
 *
 * So the rules live once, here, and a component includes a class rather than
 * re-declaring six `var()` lines. A theme adding a seventh property to an axis
 * changes this file and reaches every component that already uses the class.
 *
 * This ships with `@gamestage/tokens`, which every component already depends on,
 * so including it costs a consumer nothing they were not already installing.
 */

@layer gs.primitives {
  /* Type for anything a player presses to act: buttons, choices, commits.
   * A theme that changes the action typeface, its weight or its casing reaches
   * every one of them through this rule alone. */
  .gs-action-type {
    font-family: var(--gs-type-action-font-family);
    font-size: var(--gs-type-action-font-size);
    font-weight: var(--gs-type-action-font-weight);
    letter-spacing: var(--gs-type-action-letter-spacing);
    text-transform: var(--gs-type-action-text-transform, none);
  }

  /* Type for a number a player reads at a glance: score, stat, rank, level,
   * timer. The theme owns the face, the weight and the shadow behind it.
   *
   * text-shadow is the axis that needed this. arcade has defined
   * type.displayShadow since the beginning, one component read it by name, and
   * the other seven numbers on screen had no shadow at all. Declared here it
   * reaches every number that carries the class.
   *
   * Family, size and weight are a floor rather than a ruling: a component
   * stylesheet is unlayered, so its own font-size beats this one whatever the
   * selector, and a stat stays 22px while a podium place stays 56px. If anyone
   * ever wraps packages/ui/src/*.css in a layer, that stops being true and
   * every number jumps to the display size. Wrap this file at the same time. */
  .gs-display-type {
    font-family: var(--gs-type-display-font-family);
    font-size: var(--gs-type-display-font-size);
    font-weight: var(--gs-type-display-font-weight);
    text-shadow: var(--gs-type-display-shadow, none);
  }

  /* Case is not the library's decision, and it is not only the theme's either.
   *
   * A theme sets the default: arcade uppercases its actions because a cabinet
   * marquee shouts, paper does not. A host overrules it anywhere, on the
   * document for the whole app, on a section, or on one component, by setting
   * data-gs-case. Nothing here is baked in and nothing needs a prop on
   * twenty-five components to reach.
   *
   *   <html data-gs-case="none">            every action in sentence case
   *   <section data-gs-case="upper">        this part shouts
   *
   * The precedent is worth naming. Material UI hardcoded uppercase into its
   * button and its tabs, and a decade of issues followed from people trying to
   * turn it off, because the only way out was overriding component internals.
   * shadcn has the opposite answer and it only works because you own the source:
   * case is a utility class in a file you can edit, and the theme layer carries
   * colour and radius and no typography at all. We are a registry, so a
   * consumer does own the component file, but they should not have to edit it
   * to answer a question this ordinary.
   *
   * These rules sit in gs.primitives, which is declared after gs.theme, so a
   * host always wins over a theme. */
  [data-gs-case='upper'] {
    --gs-type-action-text-transform: uppercase;
    --gs-type-action-text-transform-primary: uppercase;
  }
  [data-gs-case='none'] {
    --gs-type-action-text-transform: none;
    --gs-type-action-text-transform-primary: none;
  }

  /* The theme's loud face lands on the primary action and nowhere else.
   *
   * arcade shouts on the action a screen is built around and leaves the rest in
   * sentence case: options, nav destinations, dismiss links. This needed a
   * second typeface while arcade drew in Bungee, which has no lowercase glyphs
   * at all, so an option computed text-transform: none and still read EASY.
   * Arcade is back on the design's own face, which has lowercase, so one font
   * does both jobs and the rule below is only about case. The drawn design does not do that. It shouts one
   * word, the one the screen is built around, and keeps the rest in sentence
   * case, and a screen with everything uppercased reads as an error message
   * rather than a game.
   *
   * Primary means one of two things, both already in the markup: the element
   * carries data-gs-variant="primary", which is a button's default, or it is
   * the commit, the control that locks an answer in.
   *
   * A theme that says nothing about primary case gets the general one: the base
   * token is declared as an alias of it, so the two move together until a theme
   * separates them. A host setting data-gs-case wins over either, because those
   * rules set both custom properties. */
  .gs-action-type:is([data-gs-variant='primary'], [data-gs-part='commit']):not([data-gs-locked='true']) {
    text-transform: var(
      --gs-type-action-text-transform-primary,
      var(--gs-type-action-text-transform, none)
    );
  }

  /* A locked primary is not the action the screen is built around while it
   * cannot be pressed, so it does not shout: specimens 1f and 2b type "Level 8"
   * and "Lv 8" in sentence case beside an uppercase START. A disabled one keeps
   * its case: 4c draws VERIFY and ENTER in capitals while they wait for input,
   * because they are still the action, only not yet. */

  /* The press gesture. A theme picks the whole transform, so it may travel on an
   * offset base, scale, or not move at all and shift colour instead.
   *
   * The transition is deliberately the only timed part: a press is movement, so
   * reduced motion zeroes it. Fill, glyph and glow changes are emphasis and are
   * not governed here, because that is how a player who cannot see movement
   * still learns what happened. */
  .gs-pressable {
    /* `motion.press` is 80ms and linear: "press is instant, no easing on the
       way down" (specimen 4a's rules and the motion table in 3i). It was
       ease-out here, which is a curve the drawing gives nothing. */
    transition:
      transform var(--gs-motion-press) var(--gs-motion-ease-press),
      box-shadow var(--gs-motion-press) var(--gs-motion-ease-press);
  }

  .gs-pressable:active:not([aria-disabled='true']):not([data-gs-disabled='true']) {
    transform: var(--gs-press-transform);
    box-shadow: var(--gs-depth-pressable-pressed);
  }

  /* A control that is not available does not move when pressed. Stated here
   * rather than in each component, for the same reason as everything else in
   * this file. */
  .gs-pressable[aria-disabled='true']:active,
  .gs-pressable[data-gs-disabled='true']:active {
    transform: none;
  }

  /* The named button style, chosen by one token.
   *
   * A style query rather than a value substitution, for identity.css's reason:
   * depth.style holds a keyword, and `box-shadow: squeeze` is invalid and would
   * compute to nothing without saying so.
   *
   * Each block remaps the three tokens a pressable control already reads,
   * rather than declaring box-shadow and transform here. That is not a detour.
   * A component stylesheet is unlayered and therefore outranks everything in
   * this layer whatever the selector, so a box-shadow written here would lose
   * to `.gs-button[data-gs-variant='primary']` and never arrive on screen; and
   * the offset base belongs to the primary variant alone, so declaring it on
   * every .gs-pressable would put a coloured slab under the ghost buttons too.
   * Remapping reaches the declaration the component already makes, and only
   * where the component makes one.
   *
   * A theme may still take a bundle apart for a bespoke look: override
   * depth.styles.<style>.pressable, or the colour and stroke tokens the bundles
   * are composed from. Overriding depth.pressable itself still reaches anything
   * that is not a .gs-pressable, which is where the base's own composition
   * lives. */
  @container style(--gs-depth-style: offset) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-offset-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-offset-pressed);
      --gs-press-transform: var(--gs-depth-styles-offset-transform);
    }
  }

  @container style(--gs-depth-style: squeeze) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-squeeze-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-squeeze-pressed);
      --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
    }
  }

  @container style(--gs-depth-style: glow) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-glow-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-glow-pressed);
      --gs-press-transform: var(--gs-depth-styles-glow-transform);
    }
  }

  /* Reduced motion, restated on the element and deliberately last.
   *
   * The build zeroes press.transform on :root, which reaches a control by
   * inheritance, and an element's own declaration beats an inherited value
   * whatever the layer. So the three blocks above would have handed every
   * pressable its theme's gesture back under prefers-reduced-motion, and the
   * default project in the browser matrix cannot see it. Same selector, same
   * specificity, same layer: source order decides, so this stays at the bottom.
   * The shadow still collapses to the pressed value, so the control answers the
   * tap without moving. */
  @media (prefers-reduced-motion: reduce) {
    .gs-pressable { --gs-press-transform: none; }
  }
}
